#!/usr/bin/env python3
"""embed_ttf - compress Montserrat.ttf with zlib and emit a C++ byte array.

Writes kernel/font/montserrat_ttf_data.cc containing the deflated font plus
the expected decompressed size so the kernel can inflate it at boot.
"""
import sys
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "tools" / "Montserrat.ttf"
OUT = ROOT / "kernel" / "font" / "montserrat_ttf_data.cc"


def main() -> int:
    raw = SRC.read_bytes()
    blob = zlib.compress(raw, 9)
    lines = [
        "// Generated by tools/embed_ttf.py - do not edit.",
        f"// zlib-deflated Montserrat.ttf, {len(raw)} -> {len(blob)} bytes.",
        "namespace hype::font {",
        "",
        "extern const unsigned char montserrat_ttf_zlib[] = {",
    ]
    for i in range(0, len(blob), 12):
        chunk = ", ".join(f"0x{b:02X}" for b in blob[i : i + 12])
        lines.append(f"    {chunk},")
    lines += [
        "};",
        f"extern const unsigned int montserrat_ttf_zlib_size = {len(blob)};",
        f"extern const unsigned int montserrat_ttf_size = {len(raw)};",
        "",
        "}  // namespace hype::font",
        "",
    ]
    OUT.write_text("\n".join(lines))
    print(f"wrote {OUT} ({len(blob)} bytes compressed from {len(raw)})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
